class Solution:
    def minimumOperationsToWriteY(self, grid: List[List[int]]) -> int:
        n = len(grid); h = n // 2
        yv = [0]*3; ov = [0]*3; yc = oc = 0
        for r in range(n):
            for c in range(n):
                isY = (r <= h and (r == c or r == n - 1 - c)) or (r > h and c == h)
                if isY:
                    yv[grid[r][c]] += 1; yc += 1
                else:
                    ov[grid[r][c]] += 1; oc += 1
        return min((yc - yv[a]) + (oc - ov[b])
                   for a in range(3) for b in range(3) if a != b)

