class Solution {
public:
    int minimumOperationsToWriteY(vector<vector<int>>& grid) {
        int n = grid.size(), h = n / 2;
        int yv[3] = {0,0,0}, ov[3] = {0,0,0}, yc = 0, oc = 0;
        for (int r = 0; r < n; r++)
            for (int c = 0; c < n; c++) {
                bool isY = (r <= h && (r == c || r == n - 1 - c)) || (r > h && c == h);
                if (isY) { yv[grid[r][c]]++; yc++; }
                else { ov[grid[r][c]]++; oc++; }
            }
        int ans = INT_MAX;
        for (int a = 0; a < 3; a++)
            for (int b = 0; b < 3; b++)
                if (a != b) ans = min(ans, (yc - yv[a]) + (oc - ov[b]));
        return ans;
    }
};

