class Solution {
    public int minimumOperationsToWriteY(int[][] grid) {
        int n = grid.length, h = n / 2;
        int[] yv = new int[3], ov = new int[3];
        int yc = 0, oc = 0;
        for (int r = 0; r < n; r++)
            for (int c = 0; c < n; c++) {
                boolean isY = (r <= h && (r == c || r == n - 1 - c)) || (r > h && c == h);
                if (isY) { yv[grid[r][c]]++; yc++; }
                else { ov[grid[r][c]]++; oc++; }
            }
        int ans = Integer.MAX_VALUE;
        for (int a = 0; a < 3; a++)
            for (int b = 0; b < 3; b++)
                if (a != b) ans = Math.min(ans, (yc - yv[a]) + (oc - ov[b]));
        return ans;
    }
}

