var minimumOperationsToWriteY = function(grid) {
    const n = grid.length, h = n >> 1;
    const yv = [0,0,0], ov = [0,0,0];
    let yc = 0, oc = 0;
    for (let r = 0; r < n; r++)
        for (let c = 0; c < n; c++) {
            const isY = (r <= h && (r === c || r === n - 1 - c)) || (r > h && c === h);
            if (isY) { yv[grid[r][c]]++; yc++; }
            else { ov[grid[r][c]]++; oc++; }
        }
    let ans = Infinity;
    for (let a = 0; a < 3; a++)
        for (let b = 0; b < 3; b++)
            if (a !== b) ans = Math.min(ans, (yc - yv[a]) + (oc - ov[b]));
    return ans;
};
